 static TextBlock Caption(string text){var label=Visuals.Label(text,14);label.FontWeight=FontWeights.SemiBold;return label;}
 void OpenHelp(){var popup=new System.Windows.Controls.Primitives.Popup{PlacementTarget=surface,Placement=System.Windows.Controls.Primitives.PlacementMode.Center,StaysOpen=false,AllowsTransparency=true};var panel=new StackPanel{Margin=new Thickness(16),Width=260};panel.Children.Add(Caption("Atalhos de teclado"));panel.Children.Add(Visuals.Label("Ctrl+N · nova nota\nCtrl+F · buscar no widget\nCtrl+, · configurações\nCtrl+Tab · próxima seção\nCtrl+B / Ctrl+I · formatação\nCtrl+V · colar texto ou imagem\nEnter no título · confirmar\nEsc · recolher a janela\nCtrl+Shift+H · ocultar notas\nCtrl+Shift+O · auto-organizar",13));panel.Children.Add(Visuals.Label("50 cores. Arraste o topo para mover; use as bordas para redimensionar.",13));var close=Visuals.TextButton("Voltar às configurações",()=>popup.IsOpen=false);panel.Children.Add(close);popup.Child=new Border{Child=panel,CornerRadius=new CornerRadius(12),Background=FluentDesign.Layer(Visuals.Dark(app.Store.Book.Theme)),BorderBrush=FluentDesign.Stroke(Visuals.Dark(app.Store.Book.Theme)),BorderThickness=new Thickness(1)};popup.Opened+=(_,_)=>close.Focus();popup.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Tab&&(Keyboard.Modifiers&ModifierKeys.Control)!=0){SelectSection((selectedSection+((Keyboard.Modifiers&ModifierKeys.Shift)!=0?sections.Count-1:1))%sections.Count);sections[selectedSection].Button.Focus();e.Handled=true;}else if(e.Key==Key.Escape){popup.IsOpen=false;e.Handled=true;}};popup.IsOpen=true;}
 StackPanel Group(string glyph,string shortName,string heading){int index=sections.Count;var page=new StackPanel{Visibility=index==0?Visibility.Visible:Visibility.Collapsed};var title=Caption(heading);title.FontSize=18;title.Margin=new Thickness(0,0,0,8);page.Children.Add(title);body.Children.Add(page);var button=Visuals.TextButton(shortName,()=>SelectSection(index));button.Height=40;button.Margin=new Thickness(2);button.Padding=new Thickness(4);var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};row.Children.Add(new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=16,Margin=new Thickness(0,0,6,0)});row.Children.Add(new TextBlock{Text=shortName,FontSize=13});button.Content=row;AutomationProperties.SetName(button,"Configurações: "+shortName);sections.Add((button,page));navigation.Children.Add(button);return page;}
 Button ActionButton(string glyph,string text,Action action){var button=Visuals.TextButton(text,action);button.Height=36;button.Margin=new Thickness(0,3,0,3);button.Padding=new Thickness(10,4,10,4);var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe Fluent Icons"),FontSize=16,Width=26,VerticalAlignment=VerticalAlignment.Center});row.Children.Add(new TextBlock{Text=text,FontSize=13,VerticalAlignment=VerticalAlignment.Center});button.Content=row;actionButtons.Add(button);return button;}
 static void SetActionLabel(Button button,string text){if(button.Content is StackPanel row&&row.Children[row.Children.Count-1] is TextBlock label)label.Text=text;AutomationProperties.SetName(button,text);}
 internal int SectionCount=>sections.Count;internal int SelectedSection=>selectedSection;
 internal void SelectSection(int index){if(index<0||index>=sections.Count)return;selectedSection=index;for(int i=0;i<sections.Count;i++)sections[i].Page.Visibility=i==index?Visibility.Visible:Visibility.Collapsed;RefreshNavigation();UpdateLayout();}
 void RefreshNavigation(){foreach(var (button,page) in sections){bool selected=page.Visibility==Visibility.Visible;FluentDesign.Select(button,selected,Visuals.Dark(app.Store.Book.Theme));AutomationProperties.SetHelpText(button,selected?"Selecionado":"");}}
 internal bool SectionsFit(){int previous=selectedSection;bool fits=true;for(int i=0;i<sections.Count;i++){SelectSection(i);foreach(var item in Descendants<FrameworkElement>(sections[i].Page).Where(e=>e.IsVisible&&(e is Button or TextBox or Slider or CheckBox))){var p=item.TranslatePoint(new Point(),this);var c=item.TranslatePoint(new Point(item.ActualWidth,item.ActualHeight),this);fits&=p.X>=0&&p.Y>=0&&c.X<=ActualWidth+1&&c.Y<=ActualHeight+1;}fits&=!Descendants<ScrollViewer>(surface).Where(s=>ReferenceEquals(s.Content,body)).Any(s=>s.ComputedVerticalScrollBarVisibility==Visibility.Visible||s.ScrollableHeight>1);}SelectSection(previous);return fits;}
 internal bool NaturalTextSize()=>!Descendants<Viewbox>(surface).Any()&&Descendants<TextBlock>(body).Where(t=>t.TemplatedParent==null).All(t=>t.FontSize>=12);
 public void ApplyTheme(){updatingOpacity=true;opacity.Value=app.Store.Book.BackgroundOpacity;opacityValue.Text=app.Store.Book.BackgroundOpacity+"%";updatingOpacity=false;SuitePanels.Theme(this,surface,app.Store.Book.Theme);foreach(var b in themes)FluentDesign.Select(b,(string)b.Tag==app.Store.Book.Theme,Visuals.Dark(app.Store.Book.Theme));foreach(var b in actionButtons)b.Background=FluentDesign.Control(Visuals.Dark(app.Store.Book.Theme));RefreshNavigation();}
 static IEnumerable<T> Descendants<T>(DependencyObject p) where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++){var c=VisualTreeHelper.GetChild(p,i);if(c is T t)yield return t;foreach(var child in Descendants<T>(c))yield return child;}}
 bool SaveOpacity(){opacitySave.Stop();if(!pendingOpacity)return true;try{app.Store.Save();pendingOpacity=false;return true;}catch(Exception e){Visuals.Error("Não foi possível salvar a opacidade. Tente novamente antes de fechar.\n"+e.Message);return false;}}
 public void Present(){Show();Activate();if(SystemParameters.ClientAreaAnimation&&!SystemParameters.HighContrast)animation=new WindowRevealAnimation(this,true,()=>{});}
 public void Dismiss(bool animate=true){if(!SaveOpacity())return;animation?.Dispose();void Finish(){closing=true;Close();}if(animate&&IsVisible&&SystemParameters.ClientAreaAnimation&&!SystemParameters.HighContrast)animation=new WindowRevealAnimation(this,false,Finish);else Finish();}
